scan_linter_check.script:
(function(engine) {
    if (!engine.rootNode) {
        return;
    }
    var ast = new global.EcsAst(engine.rootNode);
    var hits = new global.EcsSecurity(ast).basicAuthCalls();
    var report = new global.EcsReport(engine, {
        ruleId: 'SEC-004',
        title: 'Credentials set in script with setBasicAuth()',
        recommendation: 'Configure a Basic Auth profile on the REST Message, or a Connection & Credential alias, and use setAuthenticationProfile() instead of passing credentials in script.'
    });
    for (var i = 0; i < hits.length; i++) {
        report.add(hits[i].node, hits[i].message);
    }
    report.flush();
})(engine);
